import{_ as l,c as t,a2 as d,G as a,B as s,o as n}from"./chunks/framework.DUe8d0tq.js";const _=JSON.parse('{"title":"发布小程序","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/wx-release.md","filePath":"deploy/wx-release.md"}'),c={name:"deploy/wx-release.md"};function r(p,e,h,u,b,m){const i=s("NolebaseGitContributors"),o=s("NolebaseGitChangelog");return n(),t("div",null,[e[0]||(e[0]=d('<h1 id="发布小程序" tabindex="-1">发布小程序 <a class="header-anchor" href="#发布小程序" aria-label="Permalink to &quot;发布小程序&quot;">​</a></h1><p>该内容会引导您发布和部署微信小程序。</p><h2 id="_1-配置服务器域名" tabindex="-1">1. 配置服务器域名 <a class="header-anchor" href="#_1-配置服务器域名" aria-label="Permalink to &quot;1. 配置服务器域名&quot;">​</a></h2><p>在 微信小程序后台，找到菜单 <code>管理 - 开发管理 - 开发设置 - 服务器域名</code>，分别在 <code>request合法域名</code>、<code>uploadFile合法域名</code>、<code>downloadFile合法域名</code> 中填写你的 Halo 站点域名（必须是 <code>https</code>），点击 <code>保存并提交</code> 即可。</p><h2 id="_2-确认正式环境地址" tabindex="-1">2. 确认正式环境地址 <a class="header-anchor" href="#_2-确认正式环境地址" aria-label="Permalink to &quot;2. 确认正式环境地址&quot;">​</a></h2><p>发布前检查 <code>env/.env</code>（或 <code>env/.env.production</code>）中的微信正式版地址：</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VITE_SERVER_BASEURL__WEIXIN_RELEASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://你的域名&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>同时确认 <code>VITE_WX_APPID</code> 为你自己的小程序 AppID。</p><h2 id="_3-构建生产版本" tabindex="-1">3. 构建生产版本 <a class="header-anchor" href="#_3-构建生产版本" aria-label="Permalink to &quot;3. 构建生产版本&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:mp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>构建完成后会自动打开微信开发者工具并加载 <code>dist/build/mp-weixin</code> 产物。</p><h2 id="_4-预览" tabindex="-1">4. 预览 <a class="header-anchor" href="#_4-预览" aria-label="Permalink to &quot;4. 预览&quot;">​</a></h2><p>在微信开发者工具中，点击上方的 <code>预览</code> 按钮，等待片刻就可以使用微信扫码预览。</p><h2 id="_5-上传代码" tabindex="-1">5. 上传代码 <a class="header-anchor" href="#_5-上传代码" aria-label="Permalink to &quot;5. 上传代码&quot;">​</a></h2><p>预览没有问题后，在微信开发者工具中点击右上角的 <code>上传</code> 按钮，填写 <code>版本号</code> 和 <code>项目备注</code>，最后点击 <code>提交</code> 按钮，等待上传成功提示。</p><div class="tip custom-block"><p class="custom-block-title">命令行上传（可选）</p><p>项目内置了 miniprogram-ci 上传脚本，可在 CI 中使用：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload:mp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>使用前需在微信小程序后台获取上传密钥并配置 IP 白名单。</p></div><h2 id="_6-体验版" tabindex="-1">6. 体验版 <a class="header-anchor" href="#_6-体验版" aria-label="Permalink to &quot;6. 体验版&quot;">​</a></h2><p>上传成功后，打开 微信管理后台，找到菜单 <code>管理 - 版本管理 - 开发版本</code>，点击 <code>体验版</code> 按钮生成体验二维码，扫码即可体验。</p><h2 id="_7-提交审核" tabindex="-1">7. 提交审核 <a class="header-anchor" href="#_7-提交审核" aria-label="Permalink to &quot;7. 提交审核&quot;">​</a></h2><p>在微信小程序后台 <code>管理 - 版本管理 - 开发版本</code> 中，点击 <code>提交审核</code>，填写审核信息后提交。</p><details class="details custom-block"><summary>提交审核时候的建议</summary><p>为了能够更容易通过审核，作者建议：</p><ul><li><ol><li>在填写审核信息的时候，若您的小程序资质是 <code>个人资质</code>，尽可能将您的描述信息写为个人类型的内容，如：<strong>这里是我的个人日记小程序，用于记录个人的工作和生活。</strong></li></ol></li><li><ol start="2"><li>上传截图的时候，请不要截图有关于社交部分的内容，比如：评论区</li></ol></li><li><ol start="3"><li>文章内容可以先将带有分享性质的文章先进行下架，保留一些个人的日志文章等等</li></ol></li></ul></details><h2 id="_8-发布上线" tabindex="-1">8. 发布上线 <a class="header-anchor" href="#_8-发布上线" aria-label="Permalink to &quot;8. 发布上线&quot;">​</a></h2><p>等待审核通过后，在 <code>管理 - 版本管理 - 审核版本</code> 中点击 <code>发布</code> 上线即可。</p>',23)),a(i),a(o)])}const g=l(c,[["render",r]]);export{_ as __pageData,g as default};
